import pandas as pd
import matplotlib.pyplot as plt
import matplotlib.animation as animation

# 1. Load the data file generated by your C++ program
# We name the columns so Python knows which number belongs to which coordinate
columns = ['particle_x', 'particle_z', 'planet_x', 'planet_z']
data = pd.read_csv('orbit_data.csv', names=columns, encoding='utf-16')

# 2. Setup the Plotting Window (The Canvas)
fig, ax = plt.subplots(figsize=(14, 14))
ax.set_facecolor('#111111')  # Dark space background

# Set the window boundaries (Your orbit radius is 1.5e8, so we give it padding)
ax.set_xlim(-2e8, 2e8)
ax.set_ylim(-2e8, 2e8)
ax.set_title("Binary Star System Orbit Simulation (GR Research Prep)", color='white')
ax.grid(True, color='#333333', linestyle='--')

# 3. Create the visual objects on the canvas
# 'ro' means red circle, 'bo' means blue circle
particle_dot, = ax.plot([], [], 'ro', markersize=6, label='Particle')
planet_dot, = ax.plot([], [], 'bo', markersize=6, label='Planet')

particle_trail, = ax.plot([], [], 'r-', alpha=0.3, linewidth=1) # Faint red line
planet_trail, = ax.plot([], [], 'b-', alpha=0.3, linewidth=1)    # Faint blue line

ax.legend(loc='upper right')

# 4. The Animation Engine Loop (Runs frame-by-frame)
def update_frame(frame_index):
    p_x = data['particle_x'].iloc[frame_index]
    p_z = data['particle_z'].iloc[frame_index]
    pl_x = data['planet_x'].iloc[frame_index]
    pl_z = data['planet_z'].iloc[frame_index]
    
    # Update the dots
    particle_dot.set_data([p_x], [p_z])
    planet_dot.set_data([pl_x], [pl_z])
    
    # --- ADD THESE TWO LINES TO DRAW THE HISTORY ---
    # This grabs all historical positions from index 0 up to the current frame index
    particle_trail.set_data(data['particle_x'].iloc[:frame_index], data['particle_z'].iloc[:frame_index])
    planet_trail.set_data(data['planet_x'].iloc[:frame_index], data['planet_z'].iloc[:frame_index])
    
    # --- REMEMBER TO ADD THE TRAILS TO THE RETURN STATEMENT ---
    return particle_dot, planet_dot, particle_trail, planet_trail

# 5. Run the animation projector!
# interval=1 means 1 millisecond between frames. 
# step=10 skips lines so it runs fast and snappy on your screen.
ani = animation.FuncAnimation(
    fig, 
    update_frame, 
    frames=range(0, len(data), 1), 
    interval=1, 
    blit=True
)

plt.show()
